[{"order":1,"type":"heading","text":"Creating Angular Elements (Custom Elements)"},{"order":2,"type":"paragraph","text":"Angular Elements are Angular components packaged as custom elements (also known as web components), a web standard for defining new HTML elements. They allow you to use Angular components in any HTML page, regardless of the framework used (or no framework at all)."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Node.js and npm installed"},{"order":5,"type":"bullet_point","text":"Angular CLI installed globally: 'npm install -g @angular/cli'"},{"order":6,"type":"bullet_point","text":"Basic knowledge of Angular concepts"},{"order":7,"type":"subheading","text":"Step 1: Create a New Angular Project"},{"order":8,"type":"code","text":"ng new angular-elements-demo --create-application=true --defaults=true"},{"order":9,"type":"paragraph","text":"This command creates a new Angular project named 'angular-elements-demo'. The '--create-application=true' flag ensures that a default application is created, and '--defaults=true' accepts the default settings for all prompts."},{"order":10,"type":"subheading","text":"Step 2: Install Angular Elements Package"},{"order":11,"type":"code","text":"cd angular-elements-demo
npm install @angular/elements"},{"order":12,"type":"paragraph","text":"Navigate into the project directory and install the '@angular/elements' package. This package provides the necessary tools to create custom elements."},{"order":13,"type":"subheading","text":"Step 3: Create an Angular Component"},{"order":14,"type":"code","text":"ng generate component my-element"},{"order":15,"type":"paragraph","text":"This command generates a new component named 'my-element'.  Modify the 'my-element.component.ts' file."},{"order":16,"type":"code","text":"import { Component, Input, OnInit, ViewEncapsulation } from '@angular/core';

@Component({
  selector: 'app-my-element',
  template: '<p>Hello, I am {{name}}!</p>',
  styles: [],
  encapsulation: ViewEncapsulation.ShadowDom
})
export class MyElementComponent implements OnInit {
  @Input() name: string = 'World';

  constructor() { }

  ngOnInit(): void {
  }

}"},{"order":17,"type":"paragraph","text":"In this component, we've added an input property 'name' and set the 'encapsulation' to 'ViewEncapsulation.ShadowDom'. Shadow DOM provides style and markup encapsulation."},{"order":18,"type":"subheading","text":"Step 4: Convert the Component to a Custom Element"},{"order":19,"type":"paragraph","text":"Open 'app.module.ts' and modify it as follows:"},{"order":20,"type":"code","text":"import { BrowserModule } from '@angular/platform-browser';
import { NgModule, Injector } from '@angular/core';
import { createCustomElement } from '@angular/elements';
import { MyElementComponent } from './my-element/my-element.component';

import { AppComponent } from './app.component';

@NgModule({
  declarations: [
    AppComponent,
    MyElementComponent
  ],
  imports: [
    BrowserModule
  ],
  providers: [],
  bootstrap: [AppComponent],
  entryComponents: [MyElementComponent]
})
export class AppModule {
  constructor(private injector: Injector) {
    const myElement = createCustomElement(MyElementComponent, { injector: this.injector });
    customElements.define('my-custom-element', myElement);
  }

  ngDoBootstrap() {}
}"},{"order":21,"type":"bullet_point","text":"Import 'createCustomElement' from '@angular/elements'."},{"order":22,"type":"bullet_point","text":"Import 'Injector' from '@angular/core'."},{"order":23,"type":"bullet_point","text":"Add 'MyElementComponent' to the 'entryComponents' array."},{"order":24,"type":"bullet_point","text":"In the AppModule's constructor, use 'createCustomElement' to convert 'MyElementComponent' to a custom element and define it using 'customElements.define()'.  The first argument to 'customElements.define()' is the tag name you'll use in your HTML ('my-custom-element' in this case)."},{"order":25,"type":"bullet_point","text":"Remove 'AppComponent' from the 'bootstrap' array and add 'ngDoBootstrap() {}' to the AppModule class."},{"order":26,"type":"subheading","text":"Step 5: Build the Project"},{"order":27,"type":"code","text":"ng build --prod --output-hashing none"},{"order":28,"type":"paragraph","text":"Build the project in production mode. The '--output-hashing none' flag is important to prevent the generated JavaScript files from having dynamically generated names, which would make them difficult to include in other projects."},{"order":29,"type":"subheading","text":"Step 6: Create a Single JavaScript File"},{"order":30,"type":"paragraph","text":"To use the custom element, you need to combine the generated JavaScript files into a single file. You can do this using a simple command:"},{"order":31,"type":"code","text":"cd dist/angular-elements-demo
concat *.js > my-custom-element.js"},{"order":32,"type":"paragraph","text":"This command concatenates all '.js' files in the 'dist/angular-elements-demo' directory into a single file named 'my-custom-element.js'."},{"order":33,"type":"subheading","text":"Step 7: Use the Custom Element in an HTML Page"},{"order":34,"type":"paragraph","text":"Create an 'index.html' file (or modify an existing one) and include the 'my-custom-element.js' file:"},{"order":35,"type":"code","text":"<!DOCTYPE html>
<html>
<head>
  <title>Angular Element Demo</title>
  <script src="my-custom-element.js"></script>
</head>
<body>
  <my-custom-element name="Angular Element"></my-custom-element>
</body>
</html>"},{"order":36,"type":"paragraph","text":"Open the 'index.html' file in a browser. You should see the text "Hello, I am Angular Element!"."},{"order":37,"type":"subheading","text":"Troubleshooting"},{"order":38,"type":"bullet_point","text":"If the custom element doesn't render, ensure that all JavaScript files are correctly concatenated and included in the HTML page."},{"order":39,"type":"bullet_point","text":"Check the browser's developer console for any JavaScript errors."},{"order":40,"type":"bullet_point","text":"Verify that the custom element name ('my-custom-element') is correctly defined in both the Angular module and the HTML page."}]
